 33→func newAttachCmd() *cobra.Command {
 34→	var (
 35→		force     bool
 36→		agentFlag string
 37→	)
 38→	cmd := &cobra.Command{
 39→		Use:   "attach <session-id>",
 40→		Short: "Attach an existing agent session",
 41→		Long: `Attach an existing agent session that wasn't captured by hooks.
 42→
 43→This creates a checkpoint from the session's transcript and registers the
 44→session for future tracking. Use this when hooks failed to fire or weren't
 45→installed when the session started.
 46→
 47→Supported agents: claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid`,
 48→		Args: cobra.ExactArgs(1),
 49→		RunE: func(cmd *cobra.Command, args []string) error {
 50→			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
 51→				return nil
 52→			}
 53→			agentName := types.AgentName(agentFlag)
 54→			return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], agentName, force)
 55→		},
 56→	}
 57→	cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
 58→	cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid)")
 59→	return cmd
 60→}
