 62→func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
 63→	logCtx := logging.WithComponent(ctx, "attach")
 64→
 65→	repoRoot, err := validateAttachPreconditions(ctx, sessionID)
 66→	if err != nil {
 67→		return err
 68→	}
 69→
 70→	ag, transcriptPath, err := resolveAgentAndTranscript(logCtx, w, sessionID, agentName)
 71→	if err != nil {
 72→		return err
 73→	}
 74→	agentType := ag.Type()
 75→
 76→	transcriptData, err := ag.ReadTranscript(transcriptPath)
 77→	if err != nil {
 78→		return fmt.Errorf("failed to read transcript: %w", err)
 79→	}
 80→
 81→	relModifiedFiles, relNewFiles, relDeletedFiles := collectFileChanges(ctx, logCtx, ag, transcriptPath, repoRoot)
 82→
 83→	if err := strategy.EnsureSetup(ctx); err != nil {
 84→		return fmt.Errorf("failed to set up strategy: %w", err)
 85→	}
 86→
 87→	logFile, sessionDir, sessionDirAbs, err := storeTranscript(logCtx, ctx, sessionID, agentType, transcriptData)
 88→	if err != nil {
 89→		return err
 90→	}
 91→
 92→	author, err := GetGitAuthor(ctx)
 93→	if err != nil {
 94→		return fmt.Errorf("failed to get git author: %w", err)
 95→	}
 96→
 97→	meta := extractTranscriptMetadata(transcriptData)
 98→	firstPrompt := meta.FirstPrompt
 99→	commitMessage := generateCommitMessage(firstPrompt, agentType)
100→
101→	if firstPrompt != "" {
102→		promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
103→		if err := os.WriteFile(promptFile, []byte(firstPrompt), 0o600); err != nil {
104→			logging.Warn(logCtx, "failed to write prompt file", "error", err)
105→		}
106→	}
107→
108→	strat := GetStrategy(ctx)
109→	if err := strat.InitializeSession(ctx, sessionID, agentType, logFile, firstPrompt, ""); err != nil {
110→		return fmt.Errorf("failed to initialize session: %w", err)
111→	}
112→
113→	if err := enrichSessionState(logCtx, sessionID, ag, transcriptData, logFile, meta); err != nil {
114→		return err
115→	}
116→
117→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
118→	stepCtx := strategy.StepContext{
119→		SessionID:      sessionID,
120→		ModifiedFiles:  relModifiedFiles,
121→		NewFiles:       relNewFiles,
122→		DeletedFiles:   relDeletedFiles,
123→		MetadataDir:    sessionDir,
124→		MetadataDirAbs: sessionDirAbs,
125→		CommitMessage:  commitMessage,
126→		TranscriptPath: logFile,
127→		AuthorName:     author.Name,
128→		AuthorEmail:    author.Email,
129→		AgentType:      agentType,
130→	}
131→
132→	if err := strat.SaveStep(ctx, stepCtx); err != nil {
133→		return fmt.Errorf("failed to save checkpoint: %w", err)
134→	}
135→
136→	checkpointIDStr, condenseErr := condenseAndFinalizeSession(logCtx, strat, sessionID)
137→
138→	printAttachConfirmation(w, sessionID, totalChanges, condenseErr)
139→
140→	if checkpointIDStr != "" {
141→		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
142→			logging.Warn(logCtx, "failed to amend commit", "error", err)
143→			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
144→		}
145→	}
146→
147→	return nil
148→}
