150→// validateAttachPreconditions checks session ID format, git repo state, and duplicate sessions.
151→func validateAttachPreconditions(ctx context.Context, sessionID string) (string, error) {
152→	if err := validation.ValidateSessionID(sessionID); err != nil {
153→		return "", fmt.Errorf("invalid session ID: %w", err)
154→	}
155→
156→	repoRoot, err := paths.WorktreeRoot(ctx)
157→	if err != nil {
158→		return "", fmt.Errorf("not a git repository: %w", err)
159→	}
160→
161→	repo, repoErr := strategy.OpenRepository(ctx)
162→	if repoErr != nil {
163→		return "", fmt.Errorf("failed to open repository: %w", repoErr)
164→	}
165→	if strategy.IsEmptyRepository(repo) {
166→		return "", errors.New("repository has no commits yet — make an initial commit before running attach")
167→	}
168→
169→	store, err := session.NewStateStore(ctx)
170→	if err != nil {
171→		return "", fmt.Errorf("failed to open session store: %w", err)
172→	}
173→	existing, err := store.Load(ctx, sessionID)
174→	if err != nil {
175→		return "", fmt.Errorf("failed to check existing session: %w", err)
176→	}
177→	if existing != nil {
178→		return "", fmt.Errorf("session %s is already tracked by Entire", sessionID)
179→	}
180→
181→	return repoRoot, nil
182→}
