184→// resolveAgentAndTranscript resolves the agent and transcript path, with auto-detection fallback.
185→func resolveAgentAndTranscript(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName) (agent.Agent, string, error) {
186→	ag, err := agent.Get(agentName)
187→	if err != nil {
188→		return nil, "", fmt.Errorf("agent %q not available: %w", agentName, err)
189→	}
190→
191→	transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, agentName, ag)
192→	if err != nil {
193→		detectedAg, detectedPath, detectErr := detectAgentByTranscript(ctx, sessionID, agentName)
194→		if detectErr != nil {
195→			return nil, "", err
196→		}
197→		ag = detectedAg
198→		transcriptPath = detectedPath
199→		logging.Info(ctx, "auto-detected agent from transcript", "agent", ag.Name())
200→		fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
201→	}
202→
203→	return ag, transcriptPath, nil
204→}
