206→// collectFileChanges gathers modified, new, and deleted files from both transcript analysis and git status.
207→func collectFileChanges(ctx, logCtx context.Context, ag agent.Agent, transcriptPath, repoRoot string) (modified, added, deleted []string) {
208→	var transcriptFiles []string
209→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
210→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
211→			logging.Warn(logCtx, "failed to extract modified files from transcript", "error", fileErr)
212→		} else {
213→			transcriptFiles = files
214→		}
215→	}
216→
217→	changes, err := DetectFileChanges(ctx, nil)
218→	if err != nil {
219→		logging.Warn(logCtx, "failed to detect file changes, checkpoint may be incomplete", "error", err)
220→	}
221→
222→	modified = FilterAndNormalizePaths(transcriptFiles, repoRoot)
223→	if changes != nil {
224→		added = FilterAndNormalizePaths(changes.New, repoRoot)
225→		deleted = FilterAndNormalizePaths(changes.Deleted, repoRoot)
226→		modified = mergeUnique(modified, FilterAndNormalizePaths(changes.Modified, repoRoot))
227→	}
228→
229→	modified = filterToUncommittedFiles(ctx, modified, repoRoot)
230→	return modified, added, deleted
231→}
