233→// storeTranscript creates the session metadata directory and writes the (optionally normalized) transcript.
234→func storeTranscript(logCtx, ctx context.Context, sessionID string, agentType types.AgentType, transcriptData []byte) (logFile, sessionDir, sessionDirAbs string, err error) {
235→	sessionDir = paths.SessionMetadataDirFromSessionID(sessionID)
236→	sessionDirAbs, err = paths.AbsPath(ctx, sessionDir)
237→	if err != nil {
238→		return "", "", "", fmt.Errorf("failed to resolve session directory path: %w", err)
239→	}
240→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
241→		return "", "", "", fmt.Errorf("failed to create session directory: %w", err)
242→	}
243→
244→	storedTranscript := transcriptData
245→	if agentType == agent.AgentTypeGemini {
246→		if normalized, normErr := normalizeGeminiTranscript(transcriptData); normErr == nil {
247→			storedTranscript = normalized
248→		} else {
249→			logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
250→		}
251→	}
252→
253→	logFile = filepath.Join(sessionDirAbs, paths.TranscriptFileName)
254→	if err := os.WriteFile(logFile, storedTranscript, 0o600); err != nil {
255→		return "", "", "", fmt.Errorf("failed to write transcript: %w", err)
256→	}
257→	return logFile, sessionDir, sessionDirAbs, nil
258→}
