260→// printAttachConfirmation prints the post-attach status message.
261→func printAttachConfirmation(w io.Writer, sessionID string, totalChanges int, condenseErr error) {
262→	fmt.Fprintf(w, "Attached session %s\n", sessionID)
263→	if totalChanges > 0 {
264→		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
265→	} else {
266→		fmt.Fprintln(w, "  Checkpoint saved (transcript only, no uncommitted file changes detected)")
267→	}
268→	if condenseErr != nil {
269→		fmt.Fprintln(w, "  Warning: checkpoint saved on shadow branch only (condensation failed)")
270→	}
271→	fmt.Fprintln(w, "  Session is now tracked — future prompts will be captured automatically")
272→}
