274→// enrichSessionState loads the session state after initialization and populates it with
275→// transcript-derived metadata (token usage, turn count, model name, duration).
276→// The meta parameter provides pre-extracted prompt/turn/model data to avoid re-parsing.
277→func enrichSessionState(ctx context.Context, sessionID string, ag agent.Agent, transcriptData []byte, transcriptPath string, meta transcriptMetadata) error {
278→	state, err := strategy.LoadSessionState(ctx, sessionID)
279→	if err != nil {
280→		return fmt.Errorf("failed to load session state: %w", err)
281→	}
282→	if state == nil {
283→		return fmt.Errorf("session state not found after initialization (session_id=%s)", sessionID)
284→	}
285→	state.CLIVersion = versioninfo.Version
286→	state.TranscriptPath = transcriptPath
287→
288→	if usage := agent.CalculateTokenUsage(ctx, ag, transcriptData, 0, ""); usage != nil {
289→		state.TokenUsage = usage
290→	}
291→	if meta.TurnCount > 0 {
292→		state.SessionTurnCount = meta.TurnCount
293→	}
294→	if meta.Model != "" {
295→		state.ModelName = meta.Model
296→	}
297→	if dur := estimateSessionDuration(transcriptData); dur > 0 {
298→		state.SessionDurationMs = dur
299→	}
300→
301→	if err := strategy.SaveSessionState(ctx, state); err != nil {
302→		return fmt.Errorf("failed to save session state: %w", err)
303→	}
304→	return nil
305→}
