307→// condenseAndFinalizeSession condenses the session to permanent storage and transitions it to IDLE.
308→// Returns the checkpoint ID string and any condensation error.
309→func condenseAndFinalizeSession(ctx context.Context, strat *strategy.ManualCommitStrategy, sessionID string) (string, error) {
310→	var checkpointIDStr string
311→	var condenseErr error
312→	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
313→		logging.Warn(ctx, "failed to condense session", "error", err, "session_id", sessionID)
314→		condenseErr = err
315→	}
316→
317→	// Single load serves both checkpoint ID extraction and finalization
318→	state, loadErr := strategy.LoadSessionState(ctx, sessionID)
319→	if loadErr != nil {
320→		logging.Warn(ctx, "failed to load session state after condensation", "error", loadErr, "session_id", sessionID)
321→		return checkpointIDStr, condenseErr
322→	}
323→	if state == nil {
324→		return checkpointIDStr, condenseErr
325→	}
326→
327→	if condenseErr == nil {
328→		checkpointIDStr = state.LastCheckpointID.String()
329→	}
330→
331→	now := time.Now()
332→	state.LastInteractionTime = &now
333→	if transErr := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
334→		logging.Warn(ctx, "failed to transition session to idle", "error", transErr, "session_id", sessionID)
335→	}
336→	if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
337→		logging.Warn(ctx, "failed to save session state after transition", "error", saveErr, "session_id", sessionID)
338→	}
339→
340→	return checkpointIDStr, condenseErr
341→}
