343→// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
344→// project directories if needed.
345→func resolveAndValidateTranscript(ctx context.Context, sessionID string, agentName types.AgentName, ag agent.Agent) (string, error) {
346→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
347→	if err != nil {
348→		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
349→	}
350→	// If agent implements TranscriptPreparer, materialize the transcript before checking disk.
351→	if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
352→		if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
353→			logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
354→		}
355→	}
356→	// Agents use cwd-derived project directories, so the transcript may be stored under
357→	// a different project directory if the session was started from a different working directory.
358→	if _, statErr := os.Stat(transcriptPath); statErr == nil {
359→		return transcriptPath, nil
360→	}
361→	found, searchErr := searchTranscriptInProjectDirs(agentName, sessionID, ag)
362→	if searchErr == nil {
363→		logging.Info(ctx, "found transcript in alternative project directory", "path", found)
364→		return found, nil
365→	}
366→	logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
367→	return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", agentName, sessionID)
368→}
