370→// detectAgentByTranscript tries all registered agents (except skip) to find one whose
371→// transcript resolution succeeds for the given session ID.
372→func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
373→	for _, name := range agent.List() {
374→		if name == skip {
375→			continue
376→		}
377→		ag, err := agent.Get(name)
378→		if err != nil {
379→			continue
380→		}
381→		path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, name, ag)
382→		if resolveErr != nil {
383→			logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
384→			continue
385→		}
386→		return ag, path, nil
387→	}
388→	return nil, "", errors.New("transcript not found for any registered agent")
389→}
