391→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
392→// When force is true, it amends without prompting.
393→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
394→	// Get HEAD commit info
395→	repo, err := openRepository(ctx)
396→	if err != nil {
397→		return fmt.Errorf("failed to open repository: %w", err)
398→	}
399→	headRef, err := repo.Head()
400→	if err != nil {
401→		return fmt.Errorf("failed to get HEAD: %w", err)
402→	}
403→	headCommit, err := repo.CommitObject(headRef.Hash())
404→	if err != nil {
405→		return fmt.Errorf("failed to get HEAD commit: %w", err)
406→	}
407→
408→	shortHash := headRef.Hash().String()[:7]
409→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
410→
411→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
412→
413→	amend := true
414→	if !force {
415→		form := NewAccessibleForm(
416→			huh.NewGroup(
417→				huh.NewConfirm().
418→					Title("Amend the last commit in this branch?").
419→					Affirmative("Y").
420→					Negative("n").
421→					Value(&amend),
422→			),
423→		)
424→		if err := form.Run(); err != nil {
425→			return fmt.Errorf("prompt failed: %w", err)
426→		}
427→	}
428→
429→	if !amend {
430→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
431→		return nil
432→	}
433→
434→	// Skip amending if this exact checkpoint ID is already in the commit
435→	for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
436→		if existing.String() == checkpointIDStr {
437→			fmt.Fprintf(w, "Commit already has Entire-Checkpoint: %s (skipping amend)\n", checkpointIDStr)
438→			return nil
439→		}
440→	}
441→
442→	// Amend the commit with the checkpoint trailer.
443→	newMessage := appendCheckpointTrailer(headCommit.Message, checkpointIDStr)
444→
445→	// --only ensures this amend updates the commit message only and does not
446→	// accidentally include unrelated staged changes.
447→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
448→	if output, err := cmd.CombinedOutput(); err != nil {
449→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
450→	}
451→
452→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
453→	return nil
454→}
