456→// trailerLineRe matches git trailer format: "Key-Name: value" (no spaces before colon).
457→var trailerLineRe = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9-]*: `)
458→
459→// isTrailerLine reports whether a line matches git trailer format.
460→func isTrailerLine(line string) bool {
461→	return trailerLineRe.MatchString(line)
462→}
463→
464→// appendCheckpointTrailer appends Entire-Checkpoint in trailer-aware format.
465→// If the message already ends with a trailer paragraph, append directly to it;
466→// otherwise add a blank line before starting a new trailer block.
467→func appendCheckpointTrailer(message, checkpointID string) string {
468→	trimmed := strings.TrimRight(message, "\n")
469→	trailer := fmt.Sprintf("%s: %s", trailers.CheckpointTrailerKey, checkpointID)
470→
471→	lines := strings.Split(trimmed, "\n")
472→	i := len(lines) - 1
473→	for i >= 0 && strings.HasPrefix(strings.TrimSpace(lines[i]), "#") {
474→		i--
475→	}
476→
477→	hasTrailerBlock := false
478→	if i >= 0 {
479→		last := strings.TrimSpace(lines[i])
480→		if last != "" && isTrailerLine(last) {
481→			for i > 0 {
482→				i--
483→				above := strings.TrimSpace(lines[i])
484→				if strings.HasPrefix(above, "#") {
485→					continue
486→				}
487→				if above == "" {
488→					hasTrailerBlock = true
489→					break
490→				}
491→				if !isTrailerLine(above) {
492→					break
493→				}
494→			}
495→		}
496→	}
497→
498→	if hasTrailerBlock {
499→		return trimmed + "\n" + trailer + "\n"
500→	}
501→	return trimmed + "\n\n" + trailer + "\n"
502→}
