504→// transcriptMetadata holds metadata extracted from a single transcript parse pass.
505→type transcriptMetadata struct {
506→	FirstPrompt string
507→	TurnCount   int
508→	Model       string
509→}
510→
511→// extractTranscriptMetadata parses transcript bytes once and extracts the first user prompt,
512→// user turn count, and model name. Supports both JSONL (Claude Code, Cursor, OpenCode) and
513→// Gemini JSON format.
514→func extractTranscriptMetadata(data []byte) transcriptMetadata {
515→	var meta transcriptMetadata
516→
517→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
518→	lines, err := transcript.ParseFromBytes(data)
519→	if err == nil {
520→		for _, line := range lines {
521→			if line.Type == transcript.TypeUser {
522→				if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
523→					meta.TurnCount++
524→					if meta.FirstPrompt == "" {
525→						meta.FirstPrompt = prompt
526→					}
527→				}
528→			}
529→			if line.Type == transcript.TypeAssistant && meta.Model == "" {
530→				var msg struct {
531→					Model string `json:"model"`
532→				}
533→				if json.Unmarshal(line.Message, &msg) == nil && msg.Model != "" {
534→					meta.Model = msg.Model
535→				}
536→			}
537→		}
538→		if meta.TurnCount > 0 || meta.Model != "" {
539→			return meta
540→		}
541→	}
542→
543→	// Fallback: try Gemini JSON format {"messages": [...]}
544→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
545→		meta.FirstPrompt = prompts[0]
546→		meta.TurnCount = len(prompts)
547→	}
548→
549→	return meta
550→}
551→
552→// normalizeGeminiTranscript normalizes user message content fields in-place from
553→// [{"text":"..."}] arrays to plain strings, preserving all other transcript fields
554→// (timestamps, thoughts, tokens, model, toolCalls, etc.).
555→func normalizeGeminiTranscript(data []byte) ([]byte, error) {
556→	var raw map[string]json.RawMessage
557→	if err := json.Unmarshal(data, &raw); err != nil {
558→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
559→	}
560→
561→	messagesRaw, ok := raw["messages"]
562→	if !ok {
563→		return data, nil
564→	}
565→
566→	var messages []json.RawMessage
567→	if err := json.Unmarshal(messagesRaw, &messages); err != nil {
568→		return nil, fmt.Errorf("failed to parse messages: %w", err)
569→	}
570→
571→	changed := false
572→	for i, msgRaw := range messages {
573→		var msg map[string]json.RawMessage
574→		if err := json.Unmarshal(msgRaw, &msg); err != nil {
575→			continue
576→		}
577→
578→		contentRaw, hasContent := msg["content"]
579→		if !hasContent || len(contentRaw) == 0 {
580→			continue
581→		}
582→
583→		// Skip if already a string
584→		var strContent string
585→		if json.Unmarshal(contentRaw, &strContent) == nil {
586→			continue
587→		}
588→
589→		// Try to convert array of {"text":"..."} to a plain string
590→		var parts []struct {
591→			Text string `json:"text"`
592→		}
593→		if json.Unmarshal(contentRaw, &parts) != nil {
594→			continue
595→		}
596→
597→		var texts []string
598→		for _, p := range parts {
599→			if p.Text != "" {
600→				texts = append(texts, p.Text)
601→			}
602→		}
603→		joined := strings.Join(texts, "\n")
604→		strBytes, err := json.Marshal(joined)
605→		if err != nil {
606→			continue
607→		}
608→		msg["content"] = strBytes
609→		rewritten, err := json.Marshal(msg)
610→		if err != nil {
611→			continue
612→		}
613→		messages[i] = rewritten
614→		changed = true
615→	}
616→
617→	if !changed {
618→		return data, nil
619→	}
620→
621→	rewrittenMessages, err := json.Marshal(messages)
622→	if err != nil {
623→		return nil, fmt.Errorf("failed to re-serialize messages: %w", err)
624→	}
625→	raw["messages"] = rewrittenMessages
626→
627→	result, err := json.MarshalIndent(raw, "", "  ")
628→	if err != nil {
629→		return nil, fmt.Errorf("failed to re-serialize transcript: %w", err)
630→	}
631→	return result, nil
632→}
