634→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
635→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
636→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
637→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
638→func estimateSessionDuration(data []byte) int64 {
639→	type timestamped struct {
640→		Timestamp string `json:"timestamp"`
641→	}
642→
643→	var first, last time.Time
644→	for _, rawLine := range bytes.Split(data, []byte("\n")) {
645→		if len(rawLine) == 0 {
646→			continue
647→		}
648→		var ts timestamped
649→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
650→			continue
651→		}
652→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
653→		if err != nil {
654→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
655→			if err != nil {
656→				continue
657→			}
658→		}
659→		if first.IsZero() {
660→			first = parsed
661→		}
662→		last = parsed
663→	}
664→
665→	if first.IsZero() || last.IsZero() || !last.After(first) {
666→		return 0
667→	}
668→	return last.Sub(first).Milliseconds()
669→}
