189→// GetProjectHash generates a unique hash for a project based on its root path.
190→// This matches Gemini CLI's getProjectHash() which uses SHA256 of the project root.
191→func GetProjectHash(projectRoot string) string {
192→	hash := sha256.Sum256([]byte(projectRoot))
193→	return hex.EncodeToString(hash[:])
194→}
