 20→// resolveTranscriptPath determines the correct file path for an agent's session transcript.
 21→// Computes the path dynamically from the current repo location for cross-machine portability.
 22→func resolveTranscriptPath(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
 23→	repoRoot, err := paths.WorktreeRoot(ctx)
 24→	if err != nil {
 25→		return "", fmt.Errorf("failed to get worktree root: %w", err)
 26→	}
 27→
 28→	sessionDir, err := agent.GetSessionDir(repoRoot)
 29→	if err != nil {
 30→		return "", fmt.Errorf("failed to get agent session directory: %w", err)
 31→	}
 32→	return agent.ResolveSessionFile(sessionDir, sessionID), nil
 33→}
