 35→// agentSessionBaseDirs maps agent names to the base directories that contain
 36→// per-project session subdirectories. Each agent organizes transcripts under
 37→// a per-project subdirectory within its base dir.
 38→var agentSessionBaseDirs = map[types.AgentName]func() (string, error){
 39→	agentpkg.AgentNameClaudeCode: func() (string, error) {
 40→		home, err := os.UserHomeDir()
 41→		if err != nil {
 42→			return "", fmt.Errorf("failed to get home directory: %w", err)
 43→		}
 44→		return filepath.Join(home, ".claude", "projects"), nil
 45→	},
 46→	agentpkg.AgentNameGemini: func() (string, error) {
 47→		home, err := os.UserHomeDir()
 48→		if err != nil {
 49→			return "", fmt.Errorf("failed to get home directory: %w", err)
 50→		}
 51→		return filepath.Join(home, ".gemini", "tmp"), nil
 52→	},
 53→}
