 55→// searchTranscriptInProjectDirs searches for a session transcript across an agent's
 56→// project directories that could plausibly belong to the current repository.
 57→// Agents like Claude Code and Gemini CLI derive the project directory from the cwd,
 58→// so the transcript may be stored under a different project directory if the session
 59→// was started from a subdirectory.
 60→//
 61→// The search is scoped to the agent's base directory (e.g., ~/.claude/projects) and only
 62→// walks immediate subdirectories (plus one extra level for agents like Gemini that nest
 63→// chats under <project>/chats/).
 64→func searchTranscriptInProjectDirs(agentName types.AgentName, sessionID string, ag agentpkg.Agent) (string, error) {
 65→	baseDirFn, ok := agentSessionBaseDirs[agentName]
 66→	if !ok {
 67→		return "", fmt.Errorf("fallback transcript search not supported for agent %q", agentName)
 68→	}
 69→	baseDir, err := baseDirFn()
 70→	if err != nil {
 71→		return "", fmt.Errorf("failed to get base directory: %w", err)
 72→	}
 73→
 74→	// Walk subdirectories with a max depth of 3 (baseDir/project/subdir/file)
 75→	// to avoid scanning unrelated project trees.
 76→	baseDirDepth := strings.Count(filepath.Clean(baseDir), string(filepath.Separator))
 77→	const maxExtraDepth = 3
 78→
 79→	var found string
 80→	walkErr := filepath.WalkDir(baseDir, func(path string, d os.DirEntry, err error) error {
 81→		if err != nil {
 82→			return nil //nolint:nilerr // skip inaccessible dirs
 83→		}
 84→		if !d.IsDir() {
 85→			return nil
 86→		}
 87→		// Limit walk depth
 88→		depth := strings.Count(filepath.Clean(path), string(filepath.Separator)) - baseDirDepth
 89→		if depth > maxExtraDepth {
 90→			return filepath.SkipDir
 91→		}
 92→		candidate := ag.ResolveSessionFile(path, sessionID)
 93→		if _, statErr := os.Stat(candidate); statErr == nil {
 94→			found = candidate
 95→			return filepath.SkipAll
 96→		}
 97→		return nil
 98→	})
 99→	if walkErr != nil {
100→		return "", fmt.Errorf("failed to search project directories: %w", walkErr)
101→	}
102→	if found != "" {
103→		return found, nil
104→	}
105→	return "", errors.New("transcript not found in any project directory")
106→}
