126→// FindCheckpointUUID finds the UUID of the message containing the tool_result
127→// for the given tool_use_id. This is used to find the checkpoint point for
128→// transcript truncation when rewinding to a task.
129→// Returns the UUID and true if found, empty string and false otherwise.
130→func FindCheckpointUUID(lines []transcriptLine, toolUseID string) (string, bool) {
