150→// TruncateTranscriptAtUUID returns transcript lines up to and including the
151→// line with the given UUID. If the UUID is not found or is empty, returns
152→// the entire transcript.
153→//
154→//nolint:revive // Exported for testing purposes
155→func TruncateTranscriptAtUUID(lines []transcriptLine, uuid string) []transcriptLine {
156→	if uuid == "" {
157→		return lines
158→	}
159→
160→	for i, line := range lines {
161→		if line.UUID == uuid {
162→			return lines[:i+1]
163→		}
164→	}
165→
166→	// UUID not found, return full transcript
167→	return lines
168→}
