170→// writeTranscript writes transcript lines to a file in JSONL format.
171→func writeTranscript(path string, lines []transcriptLine) error {
172→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
173→	if err != nil {
174→		return fmt.Errorf("failed to create file: %w", err)
175→	}
176→	defer func() { _ = file.Close() }()
177→
178→	for _, line := range lines {
179→		data, err := json.Marshal(line)
180→		if err != nil {
181→			return fmt.Errorf("failed to marshal line: %w", err)
182→		}
183→		if _, err := file.Write(data); err != nil {
184→			return fmt.Errorf("failed to write line: %w", err)
185→		}
186→		if _, err := file.WriteString("\n"); err != nil {
187→			return fmt.Errorf("failed to write newline: %w", err)
188→		}
189→	}
190→
191→	return nil
192→}
