200→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
201→// Returns empty position if file doesn't exist or is empty.
202→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
203→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
204→	if path == "" {
205→		return TranscriptPosition{}, nil
206→	}
207→
208→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
209→	if err != nil {
210→		if os.IsNotExist(err) {
211→			return TranscriptPosition{}, nil
212→		}
213→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
214→	}
215→	defer func() { _ = file.Close() }()
216→
217→	var pos TranscriptPosition
218→	reader := bufio.NewReader(file)
219→
220→	for {
221→		lineBytes, err := reader.ReadBytes('\n')
222→		if err != nil && err != io.EOF {
223→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
224→		}
225→
226→		if len(lineBytes) == 0 {
227→			if err == io.EOF {
228→				break
229→			}
230→			continue
231→		}
232→
233→		pos.LineCount++
234→
235→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
236→		var line transcriptLine
237→		if err := json.Unmarshal(lineBytes, &line); err == nil {
238→			if line.UUID != "" {
239→				pos.LastUUID = line.UUID
240→			}
241→		}
242→
243→		if err == io.EOF {
244→			break
245→		}
246→	}
247→
248→	return pos, nil
249→}
