201→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
202→	if err != nil {
203→		if os.IsNotExist(err) {
204→			return "", nil
205→		}
206→		return "", fmt.Errorf("failed to read transcript: %w", err)
